  let pptxModulePromise=null;
  function loadPptxModule(){return pptxModulePromise??=import("./vendor/pptx-renderer/pptx-renderer.browser.es.js")}
  async function inspectMaterialFile(file){if(!(file instanceof File)||!file.size)throw Error("올릴 PDF, PPTX 또는 이미지 파일을 선택해 주세요.");if(/\.ppt$/i.test(file.name))throw Error("구형 PPT 파일은 바로 표시할 수 없습니다. PowerPoint에서 PPTX로 다시 저장한 뒤 올려 주세요.");let pageCount=1;if(/\.pdf$/i.test(file.name)||file.type==='application/pdf'){if(!window.pdfjsLib)throw Error("PDF 기능을 불러오지 못했습니다. 페이지를 새로고침한 뒤 다시 시도해 주세요.");const pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;pageCount=pdf.numPages;await pdf.destroy()}else if(/\.pptx$/i.test(file.name)||file.type==='application/vnd.openxmlformats-officedocument.presentationml.presentation'){const {parseZip,buildPresentation,RECOMMENDED_ZIP_LIMITS}=await loadPptxModule();const presentation=buildPresentation(await parseZip(await file.arrayBuffer(),RECOMMENDED_ZIP_LIMITS),{lazySlides:true});pageCount=presentation.slides.length;if(!pageCount)throw Error("PPTX 안에서 표시할 슬라이드를 찾지 못했습니다.")}else if(!/^image\/(png|jpeg|webp)$/i.test(file.type))throw Error("PDF, PPTX, PNG, JPG, WEBP 파일만 올릴 수 있습니다.");return pageCount}
  async function uploadMaterialFile(file){const pageCount=await inspectMaterialFile(file),safe=`${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"_")}`,path=`shared/${remote.user.id}/${safe}`;const {error}=await db.storage.from("class-materials").upload(path,file,{contentType:file.type||undefined});if(error)throw error;return{path,pageCount}}
  const materialFileField='<label>PDF, PPTX 또는 이미지<input name="file" type="file" accept=".pdf,.pptx,application/pdf,application/vnd.openxmlformats-officedocument.presentationml.presentation,image/png,image/jpeg,image/webp"></label>';
