  function materialForm(){modalForm("전체 공유 수업 자료 올리기",`<p class="shared-notice">PDF와 PPTX는 슬라이드별로 자동 표시됩니다. 구형 PPT 파일은 PowerPoint에서 PPTX로 저장한 뒤 올려 주세요.</p><label>자료 종류<select name="kind"><option value="slide">수업 슬라이드</option><option value="worksheet">학습지</option></select></label><label>제목<input name="title" required></label><label>설명<textarea name="description"></textarea></label>${requiredMaterialFileField}`,async fd=>{const file=fd.get("file"),uploaded=await uploadMaterialFile(file);const {error}=await db.from("materials").insert({class_id:null,teacher_id:remote.user.id,kind:fd.get("kind"),title:String(fd.get("title")).trim(),description:String(fd.get("description")||"").trim(),file_path:uploaded.path,page_count:uploaded.pageCount});if(error){await db.storage.from("class-materials").remove([uploaded.path]);throw error}})}
  function editMaterialForm(material){modalForm("수업 자료 수정",`<p class="shared-notice">제목과 설명만 수정하려면 새 파일을 선택하지 않아도 됩니다.</p><label>자료 종류<select name="kind"><option value="slide" ${material.type==='slide'?'selected':''}>수업 슬라이드</option><option value="worksheet" ${material.type==='worksheet'?'selected':''}>학습지</option></select></label><label>제목<input name="title" required value="${escapeHtml(material.title)}"></label><label>설명<textarea name="description">${escapeHtml(material.desc)}</textarea></label>${materialFileField}<small>새 파일을 선택하면 현재 슬라이드 파일이 교체됩니다.</small>`,async fd=>{const file=fd.get("file"),replacement=file instanceof File&&file.size?await uploadMaterialFile(file):null,changes={kind:fd.get("kind"),title:String(fd.get("title")).trim(),description:String(fd.get("description")||"").trim()};if(replacement){changes.file_path=replacement.path;changes.page_count=replacement.pageCount}const {error}=await db.from("materials").update(changes).eq("id",material.id).eq("teacher_id",remote.user.id);if(error){if(replacement)await db.storage.from("class-materials").remove([replacement.path]);throw error}if(replacement&&material.filePath){const {error:fileError}=await db.storage.from("class-materials").remove([material.filePath]);if(fileError)console.warn("이전 자료 파일 정리 실패",fileError)}})}
  function normalizeActivityUrl(value){let url;try{url=new URL(String(value).trim())}catch{throw Error("https://로 시작하는 올바른 활동 링크를 입력해 주세요.")}if(!['http:','https:'].includes(url.protocol))throw Error("http 또는 https 링크만 등록할 수 있습니다.");return url.href}
